INSERT INTO `algorithm_config` VALUES ('auto_compensation_enabled','2026-07-09 23:39:47.637150','Tự động tạo ngày nghỉ bù sau mỗi ca trực 24/24 theo quy tắc bù ca đã quy định. Tắt OFF nếu muốn quản lý nghỉ bù thủ công.','true','2026-07-09 23:42:58.172096','BOOLEAN',NULL),('auto_gen_enabled','2026-07-09 23:39:47.637150','Tự động tạo yêu cầu nhân sự khi mở kỳ lịch mới.','true','2026-07-09 23:42:58.156726','BOOLEAN',NULL),('auto_gen_holiday_mode','2026-07-09 23:39:47.637150','Xử lý ngày lễ: SKIP = bỏ qua, PARTIAL = giảm cường độ.','SKIP','2026-07-09 23:42:58.206383','STRING',NULL),('auto_gen_l01_allowed_specialties','2026-07-09 23:39:47.637150','Danh sách chuyên khoa được gán L01 (trực 24/24). Rỗng = mặc định Ngoại,Nội. Ví dụ: Ngoại,Nội,Sản,Nhi,Mắt,Răng','Ngoại,Nội,Sản,Nhi,Mắt,Răng','2026-07-15 13:35:35.209872','STRING',NULL),('auto_gen_l01_max_per_day','2026-07-09 23:39:47.637150','Trần khuyến nghị L01 mỗi ngày khi sinh mục tiêu. 0 = không đặt trần.','4','2026-07-10 04:46:20.000000','NUMBER',NULL),('auto_gen_l01_max_per_week','2026-07-09 23:39:47.637150','Số ca L01 tối đa mỗi người mỗi tuần. 0 = không giới hạn.','3','2026-07-13 13:41:55.934766','NUMBER',NULL),('auto_gen_l01_min_per_day','2026-07-09 23:39:47.637150','Mục tiêu nhân sự L01 mỗi ngày; thuật toán cố gắng đạt nhưng không phá ràng buộc cứng.','3','2026-07-10 04:46:22.000000','NUMBER',NULL),('auto_gen_l01_min_per_week','2026-07-09 23:39:47.637150','Số ca L01 tối thiểu mỗi người mỗi tuần.','2','2026-07-13 13:41:55.917964','NUMBER',NULL),('auto_gen_l02_allowed_specialties','2026-07-09 23:39:47.637150','Danh sách chuyên khoa được gán L02 (thông tầm). Rỗng = mặc định Ngoại,Nội.','N?i,Ngo?i,Rang,Nhi,S?n,M?t','2026-07-15 02:20:21.629277','STRING',NULL),('auto_gen_l02_max_per_day','2026-07-09 23:39:47.637150','Trần khuyến nghị L02 mỗi ngày khi sinh mục tiêu. 0 = không đặt trần.','5','2026-07-13 13:41:55.917964','NUMBER',NULL),('auto_gen_l02_max_per_week','2026-07-09 23:39:47.637150','Số ca L02 tối đa mỗi người mỗi tuần. 0 = không giới hạn.','4','2026-07-13 13:41:55.934766','NUMBER',NULL),('auto_gen_l02_min_per_day','2026-07-09 23:39:47.637150','Mục tiêu nhân sự L02 mỗi ngày; thuật toán cố gắng đạt nhưng không phá ràng buộc cứng.','3','2026-07-10 04:46:24.000000','NUMBER',NULL),('auto_gen_l02_min_per_week','2026-07-09 23:39:47.637150','Số ca L02 tối thiểu mỗi người mỗi tuần.','3','2026-07-13 13:41:55.917964','NUMBER',NULL),('auto_gen_l03_allowed_specialties','2026-07-09 23:39:47.637150','Danh sách chuyên khoa được gán L03 (phòng khám dịch vụ). Rỗng = mặc định Ngoại,Nội.','N?i,Ngo?i,Rang,Nhi,S?n,M?t','2026-07-15 02:20:21.630277','STRING',NULL),('auto_gen_l03_max_per_day','2026-07-09 23:39:47.637150','Trần khuyến nghị L03 mỗi ngày khi sinh mục tiêu. 0 = không đặt trần.','6','2026-07-13 13:41:55.917964','NUMBER',NULL),('auto_gen_l03_max_per_week','2026-07-09 23:39:47.637150','Số ca L03 tối đa mỗi người mỗi tuần. 0 = không giới hạn.','5','2026-07-13 13:41:55.934766','NUMBER',NULL),('auto_gen_l03_min_per_day','2026-07-09 23:39:47.637150','Mục tiêu nhân sự L03 mỗi ngày; thuật toán cố gắng đạt nhưng không phá ràng buộc cứng.','4','2026-07-13 13:41:55.901541','NUMBER',NULL),('auto_gen_l03_min_per_week','2026-07-09 23:39:47.637150','Số ca L03 tối thiểu mỗi người mỗi tuần.','3','2026-07-13 13:41:55.917964','NUMBER',NULL),('AUTO_GEN_L04_ALLOWED_SPECIALTIES','2026-07-09 23:42:58.219358','Danh sách chuyên khoa được gán L04. Rỗng = tất cả chuyên khoa. Ví dụ: Ngoại,Nội,Sản','','2026-07-13 13:41:55.934766','STRING',NULL),('auto_gen_l04_cross_specialty','2026-07-09 23:39:47.637150','Cho phép gán nhân sự từ chuyên khoa khác vào L04 khi chuyên khoa gốc thiếu nhân sự.','true','2026-07-15 02:38:21.770098','BOOLEAN',NULL),('auto_gen_l04_cross_specialty_ratio','2026-07-09 23:39:47.637150','Ngưỡng shortage L04 (0.0-1.0) để kích hoạt cross-specialty. Ví dụ: 0.5 = chỉ dùng cross khi strict thiếu ≥ 50%. 0.0 = không bao giờ. 1.0 = dùng cross khi thiếu bất kỳ.','1.0','2026-07-15 13:35:35.209872','NUMBER',NULL),('auto_gen_l04_max_per_day','2026-07-09 23:39:47.637150','Trần khuyến nghị L04 mỗi ngày/chuyên khoa khi sinh mục tiêu. 0 = không đặt trần.','12','2026-07-15 02:38:21.750660','NUMBER',NULL),('auto_gen_l04_max_per_week','2026-07-09 23:39:47.637150','Số ca L04 tối đa mỗi người mỗi tuần. 0 = không giới hạn.','12','2026-07-15 02:38:21.768092','NUMBER',NULL),('auto_gen_l04_min_per_day','2026-07-09 23:39:47.637150','Mục tiêu nhân sự L04 mỗi ngày/chuyên khoa; thuật toán cố gắng đạt nhưng không phá ràng buộc cứng.','6','2026-07-13 13:41:55.916534','NUMBER',NULL),('auto_gen_l04_min_per_week','2026-07-09 23:39:47.637150','Số ca L04 tối thiểu mỗi người mỗi tuần.','3','2026-07-15 02:38:21.765050','NUMBER',NULL),('AUTO_GEN_REMOVED_SHIFT_TYPES','2026-07-09 23:42:58.206383','Danh sách mã loại lịch (L01..L04) bị bỏ qua khi tự động tạo yêu cầu. Phân tách bằng dấu phẩy. Rỗng = không bỏ.','','2026-07-09 23:42:58.206383','STRING',NULL),('backtrack_time_limit_seconds','2026-07-09 23:39:47.637150','Thời gian tối đa cho phép thuật toán backtracking chạy (giây). Hết thời gian → dừng và trả kết quả tốt nhất đã tìm được.','60','2026-07-09 23:42:58.172096','NUMBER',NULL),('balance_score_min','2026-07-09 23:39:47.637150','Ngưỡng điểm cân bằng tải tối thiểu (0.0–1.0). Cao → phân bổ ca trực công bằng hơn nhưng có thể khó đạt; thấp → dễ đáp ứng nhưng có thể thiên lệch.','0.7','2026-07-09 23:42:58.172096','NUMBER',NULL),('greedy_coverage_threshold','2026-07-09 23:39:47.637150','Ngưỡng phủ lịch tối thiểu (0.0–1.0). Khi tỷ lệ lịch đã phủ đạt mức này, thuật toán greedy sẽ dừng sớm. Giảm → chạy nhanh hơn; tăng → phủ kỹ hơn.','0.85','2026-07-09 23:42:58.170291','NUMBER',NULL),('max_iterations','2026-07-09 23:39:47.637150','Số vòng lặp tối đa cho thuật toán backtracking. Tăng lên nếu thuật toán chưa hết thời gian mà vẫn chưa tìm được lời giải tốt; giảm xuống nếu chạy quá lâu.','1000','2026-07-09 23:42:58.156726','NUMBER',NULL),('max_shifts_per_staff','2026-07-09 23:39:47.637150','Số ca trực tối đa mỗi nhân sự trong kỳ. Đặt 0 để dùng maxShiftsPerMonth của nhân sự. Giới hạn này ngược lại với min — ngăn không ai bị quá tải.','0','2026-07-13 13:41:55.835363','NUMBER',NULL),('max_staff_per_shift','2026-07-09 23:39:47.637150','Số nhân sự tối đa mỗi ca. Đặt 0 để không giới hạn. Giới hạn này chỉ áp dụng khi yêu cầu ca có requiredStaffCount > maxStaffPerShift.','0','2026-07-09 23:42:58.172096','NUMBER',NULL),('min_shifts_per_staff','2026-07-09 23:39:47.637150','Số ca trực tối thiểu mỗi nhân sự trong kỳ. Đặt 0 để bỏ qua. Giúp đảm bảo mỗi người đều có ít nhất N ca trong kỳ.','0','2026-07-09 23:42:58.188058','NUMBER',NULL),('min_staff_per_shift','2026-07-09 23:39:47.637150','Số nhân sự tối thiểu mỗi ca. Đặt 0 để bỏ qua giới hạn này. Nếu không đủ nhân sự đạt ngưỡng, thuật toán sẽ cảnh báo nhưng vẫn xếp.','1','2026-07-09 23:42:58.172096','NUMBER',NULL),('overnight_recovery_hours','2026-07-09 23:39:47.637150','Khoảng cách nghỉ bắt buộc giữa hai ca trực 24/24 liên tiếp của cùng một người. Thường đặt 24h để đảm bảo nghỉ ngơi đủ.','24','2026-07-09 23:42:58.156726','NUMBER',NULL),('permissions.version','2026-07-14 02:35:00.669946','Permission matrix version (epoch ms). Bumped whenever role_permission rows change; compared with the permVer claim in JWTs to invalidate stale tokens.','1784020000000','2026-07-14 19:37:28.870554','STRING',NULL),('weekend_weight','2026-07-09 23:39:47.637150','Hệ số phạt khi xếp lịch cho người vào thứ 7 / chủ nhật. Giá trị càng cao → thuật toán càng tránh xếp ca cuối tuần. Đặt 1 để tắt ưu tiên.','1.5','2026-07-09 23:42:58.156726','NUMBER',NULL);
